function isPalindrome(s) {
  const t = s.toLowerCase();
  for (let i = 0, j = t.length - 1; i < j; i++, j--) {
    if (t[i] !== t[j]) return false;
  }
  return true;
}

function compact(events) {
  const filtered = events.filter((e) => e.v !== null && e.v !== undefined);
  const out = [];
  for (const e of filtered) {
    const last = out[out.length - 1];
    if (last !== undefined && last.v === e.v) continue;
    out.push({ t: e.t, v: e.v });
  }
  return out;
}

function parseAssignments(text) {
  const out = {};
  const set = (k, v) => Object.defineProperty(out, k, {
    value: v, writable: true, enumerable: true, configurable: true
  });
  const stripComment = (line) => {
    let inStr = false;
    for (let i = 0; i < line.length; i++) {
      const c = line[i];
      if (inStr) {
        if (c === '\\') i++;
        else if (c === '"') inStr = false;
      } else if (c === '"') inStr = true;
      else if (c === '#') return line.slice(0, i);
    }
    return line;
  };
  for (const raw of String(text).split(/\r\n|\n|\r/)) {
    const line = stripComment(raw).trim();
    if (!line) continue;
    const m = /^([A-Za-z0-9_]+)\s*=\s*(.*)$/.exec(line);
    if (!m) continue;
    const key = m[1];
    const rest = m[2];
    let value;
    if (rest.charAt(0) === '"') {
      let v = '';
      let i = 1;
      for (; i < rest.length; i++) {
        const c = rest[i];
        if (c === '\\' && i + 1 < rest.length) {
          const n = rest[++i];
          if (n === 'n') v += '\n';
          else if (n === '"') v += '"';
          else if (n === '\\') v += '\\';
          else v += n;
        } else if (c === '"') {
          break;
        } else {
          v += c;
        }
      }
      value = v;
    } else {
      const b = /^[A-Za-z0-9_]+/.exec(rest);
      if (!b) continue;
      value = b[0];
    }
    set(key, value);
  }
  return out;
}

function orderJobs(jobs) {
  if (!Array.isArray(jobs) || jobs.length === 0) return [];

  const idSet = new Set();
  for (const job of jobs) {
    if (!job || typeof job.id !== "string" || idSet.has(job.id)) return null;
    idSet.add(job.id);
  }

  const depsOf = new Map();
  const dependents = new Map();
  const remaining = new Map();

  for (const job of jobs) {
    const deps = Array.isArray(job.deps) ? job.deps : [];
    const uniqueDeps = [...new Set(deps)];
    for (const dep of uniqueDeps) {
      if (!idSet.has(dep)) return null;
    }
    depsOf.set(job.id, uniqueDeps);
    remaining.set(job.id, uniqueDeps.length);
    if (!dependents.has(job.id)) dependents.set(job.id, []);
    for (const dep of uniqueDeps) {
      if (!dependents.has(dep)) dependents.set(dep, []);
      dependents.get(dep).push(job.id);
    }
  }

  const heap = [];
  const push = (id) => {
    heap.push(id);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent] <= heap[i]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = i * 2 + 1;
        const r = l + 1;
        let smallest = i;
        if (l < heap.length && heap[l] < heap[smallest]) smallest = l;
        if (r < heap.length && heap[r] < heap[smallest]) smallest = r;
        if (smallest === i) break;
        [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
        i = smallest;
      }
    }
    return top;
  };

  for (const job of jobs) {
    if (remaining.get(job.id) === 0) push(job.id);
  }

  const order = [];
  while (heap.length > 0) {
    const id = pop();
    order.push(id);
    for (const next of dependents.get(id) || []) {
      const left = remaining.get(next) - 1;
      remaining.set(next, left);
      if (left === 0) push(next);
    }
  }

  return order.length === jobs.length ? order : null;
}

function roundHalfEven(x, digits) {
  const factor = 10 ** digits;
  const scaled = x * factor;
  const floor = Math.floor(scaled);
  const frac = scaled - floor;
  let result;
  if (frac > 0.5) {
    result = floor + 1;
  } else if (frac < 0.5) {
    result = floor;
  } else {
    result = floor % 2 === 0 ? floor : floor + 1;
  }
  return result / factor;
}
